   yy2,xx2=np.array(pts).T;xyz=w[yy2,xx2,:3];res.append((len(pts),(xx2.min(),yy2.min(),xx2.max(),yy2.max()),xyz.mean(0),xyz.std(0),im[yy2,xx2].mean(0)))
